"""Sign subgroup of the group generated by Cayley-Dickson basis left multiplications.

L_{e_m} e_x = psi_n(m, x) e_{m^x} with psi_n = cd_sign(2^n, m, x). Every element
of G_n = <L_{e_m}> is a signed XOR translation, and the diagonal kernel H_n of
G_n -> F_2^n is spanned over F_2 by the Schreier sign vectors

    s_{a,b}(x) = phi(b, x) + phi(a, b^x) + phi(a^b, x),   phi = [psi = -1].

A vector on F_2^n is a Python int whose bit x is the value at index x. Bit n-1
of the index is the last doubling: cd_sign splits on index >= dim/2 first. For
n >= 3 the span equals U_n, the even-weight functions of the low n-1 index
bits plus the indicator of index bit n-1; for n = 2 it is the constants.
literature/notes/left_mult_sign_rank.md proves this for every n; the checker
tests each lemma of the proof and the statement itself at every n up to --max-n,
the closed form at n <= 7 only:

  recursion   psi_n from psi_{n-1} by the four doubling cases of cd_sign
  commutator  phi(c,y) + phi(y,c) = [c != 0][y != 0][c != y]
  parity      every row and column of phi_n has even weight (n >= 2)
  closed form s_{a,b} from level-(n-1) rows and columns, cell by cell
  upper       every s_{a,b} lies in U_n
  lower       every basis vector of U_n reduces to zero against span{s_{a,b}}
  rank        F_2 rank of the distinct s_{a,b} by full elimination
  degree      every span basis vector has ANF degree <= n-2, attained

Any mismatch prints the failing statement to stderr and exits 1. Stdout is
byte-deterministic; --timing adds per-level seconds on stderr.
"""

from __future__ import annotations

import argparse
import sys
import time
from collections.abc import Callable
from pathlib import Path


class Mismatch(Exception):
    pass


def _require(ok: bool, message: str) -> None:
    if not ok:
        raise Mismatch(message)


def _low_masks(n: int) -> list[int]:
    """M_i has bit x set where index bit i of x is 0, for a 2^n-bit vector."""
    dim = 1 << n
    return [sum(1 << x for x in range(dim) if not (x >> i) & 1) for i in range(n)]


def _translate(v: int, c: int, masks: list[int]) -> int:
    """Bit x of the result is bit x ^ c of v."""
    i = 0
    while c:
        if c & 1:
            step = 1 << i
            m = masks[i]
            v = ((v & m) << step) | ((v >> step) & m)
        c >>= 1
        i += 1
    return v


def _anf(v: int, masks: list[int]) -> int:
    """Moebius transform: bit m of the result is the ANF coefficient of x^m."""
    for i, m in enumerate(masks):
        v ^= (v & m) << (1 << i)
    return v


def _rows_and_columns(n: int, sign: Callable[[int, int, int], int]) -> tuple[list[int], list[int]]:
    dim = 1 << n
    rows = [sum(1 << x for x in range(dim) if sign(dim, m, x) < 0) for m in range(dim)]
    cols = [sum(1 << x for x in range(dim) if (rows[x] >> c) & 1) for c in range(dim)]
    return rows, cols


def _check_recursion(n: int, rows: list[int], prev_rows: list[int], prev_cols: list[int]) -> None:
    """Row (a', alpha) of phi_n is phi_{n-1}(a', .) + alpha N on xi = 0 and
    phi_{n-1}(., a') + alpha delta_0 on xi = 1, with N = [x' != 0]."""
    half = 1 << (n - 1)
    low = (1 << half) - 1
    not_zero = low ^ 1
    for a in range(1 << n):
        a_low, alpha = a & (half - 1), a >> (n - 1)
        want = (prev_rows[a_low] ^ (not_zero if alpha else 0)) | ((prev_cols[a_low] ^ (1 if alpha else 0)) << half)
        _require(rows[a] == want, f"n={n}: row {a} departs from the doubling recursion")


def _check_commutator_and_parity(n: int, rows: list[int], cols: list[int]) -> None:
    dim = 1 << n
    full = (1 << dim) - 1
    for c in range(dim):
        want = 0 if c == 0 else full ^ 1 ^ (1 << c)
        _require(rows[c] ^ cols[c] == want, f"n={n}: commutator row {c} is not [c != 0][y != 0][c != y]")
        if n >= 2:
            _require(rows[c].bit_count() % 2 == 0, f"n={n}: row {c} has odd weight")
            _require(cols[c].bit_count() % 2 == 0, f"n={n}: column {c} has odd weight")


def _check_closed_form(n: int, prev_rows: list[int], prev_cols: list[int], rows: list[int], masks: list[int]) -> None:
    """s_{a,b}(x', xi) = phi_xi(b',x') + phi_xi(a'^b',x') + phi_{beta+xi}(a', b'^x')
    + alpha (delta_0 + delta_{b'} + beta)(x'), with phi_0 = phi, phi_1 = phi transposed."""
    dim = 1 << n
    half = dim >> 1
    low = (1 << half) - 1
    low_masks = masks[: n - 1]
    by_xi = (prev_rows, prev_cols)
    for a in range(dim):
        a_low, alpha = a & (half - 1), a >> (n - 1)
        for b in range(dim):
            b_low, beta = b & (half - 1), b >> (n - 1)
            halves = []
            for xi in (0, 1):
                part = by_xi[xi][b_low] ^ by_xi[xi][a_low ^ b_low]
                part ^= _translate(by_xi[(beta + xi) & 1][a_low], b_low, low_masks)
                if alpha:
                    part ^= 1 ^ (1 << b_low) ^ (low if beta else 0)
                halves.append(part)
            direct = rows[b] ^ _translate(rows[a], b, masks) ^ rows[a ^ b]
            _require(direct == halves[0] | (halves[1] << half), f"n={n}: closed form fails at a={a} b={b}")


def _in_explicit_space(v: int, n: int) -> bool:
    """U_n: even-weight function of the low n-1 bits plus c [x_{n-1}] (c = 0 at n = 2)."""
    half = 1 << (n - 1)
    low = (1 << half) - 1
    lo, hi = v & low, v >> half
    top_ok = lo == hi if n == 2 else lo ^ hi in (0, low)
    return top_ok and lo.bit_count() % 2 == 0 and hi.bit_count() % 2 == 0


def _explicit_basis(n: int) -> list[int]:
    half = 1 << (n - 1)
    low = (1 << half) - 1
    basis = [(1 | (1 << c)) * (1 | (1 << half)) for c in range(1, half)]
    if n >= 3:
        basis.append(low << half)
    return basis


def _reduce(v: int, pivots: dict[int, int]) -> int:
    while v:
        p = pivots.get(v.bit_length() - 1)
        if p is None:
            return v
        v ^= p
    return 0


def check_level(
    n: int, rows: list[int], cols: list[int], prev: tuple[list[int], list[int]] | None
) -> tuple[int, int, int, int]:
    """Return (distinct s_{a,b}, rank, max ANF degree of the span, log2 |G_n|)."""
    dim = 1 << n
    masks = _low_masks(n)
    _check_commutator_and_parity(n, rows, cols)
    if prev is not None:
        _check_recursion(n, rows, *prev)
        if n <= 7:
            _check_closed_form(n, prev[0], prev[1], rows, masks)

    distinct: set[int] = set()
    for b in range(dim):
        fb = rows[b]
        for a in range(dim):
            distinct.add(fb ^ _translate(rows[a], b, masks) ^ rows[a ^ b])
    for v in sorted(distinct):
        _require(_in_explicit_space(v, n), f"n={n}: a Schreier sign vector lies outside U_n")

    pivots: dict[int, int] = {}
    for v in sorted(distinct):
        r = _reduce(v, pivots)
        if r:
            pivots[r.bit_length() - 1] = r
    rank = len(pivots)
    want = 1 if n == 2 else 1 << (n - 1)
    _require(rank == want, f"n={n}: rank {rank}, expected {want}")
    explicit = _explicit_basis(n)
    _require(len(explicit) == want, f"n={n}: explicit basis has {len(explicit)} vectors, expected {want}")
    for u in explicit:
        _require(_reduce(u, pivots) == 0, f"n={n}: a U_n basis vector lies outside the Schreier span")

    too_high = sum(1 << m for m in range(dim) if m.bit_count() > max(n - 2, 0))
    exact = sum(1 << m for m in range(dim) if m.bit_count() == max(n - 2, 0))
    reach = 0
    for v in pivots.values():
        coefficients = _anf(v, masks)
        _require(coefficients & too_high == 0, f"n={n}: span vector of ANF degree above {max(n - 2, 0)}")
        reach |= coefficients & exact
    _require(reach != 0, f"n={n}: no span vector reaches ANF degree {max(n - 2, 0)}")
    return len(distinct), rank, max(n - 2, 0), n + rank


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--max-n", type=int, default=8, help="largest n = log2(dim), at least 2")
    parser.add_argument("--timing", action="store_true", help="print per-level seconds on stderr")
    args = parser.parse_args()
    if args.max_n < 2:
        parser.error("--max-n must be at least 2")

    sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "gororoba_quantum"))
    from cd_core import cd_sign

    print("n dim distinct_s rank max_deg log2|G|")
    prev: tuple[list[int], list[int]] | None = None
    try:
        for n in range(1, args.max_n + 1):
            start = time.perf_counter()
            rows, cols = _rows_and_columns(n, cd_sign)
            if n >= 2:
                distinct, rank, degree, order = check_level(n, rows, cols, prev)
                print(f"{n} {1 << n} {distinct} {rank} {degree} {order}")
                if args.timing:
                    print(f"n={n}: {time.perf_counter() - start:.2f} s", file=sys.stderr)
            prev = (rows, cols)
    except Mismatch as exc:
        print(f"mismatch: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
